// ===== 登录头辅助 =====
function getHeaderMap(_){
	var src = (_ && _.source) ? _.source : source;
	var infomap = "";
	try{ infomap = String(src.getLoginHeader()).replace(/^#/,''); }catch(e){}
	infomap = (infomap!="null"&&infomap!=""&&infomap!=null)?infomap:"{}";
	try{ return JSON.parse(infomap); }catch(e){ return {}; }
}
function setHeaders(){
	var map = getHeaderMap(this);
	for(var i=0;i<arguments.length;i++){
		var k = String(arguments[i]).split("=")[0];
		var v = String(arguments[i]).split("=")[1];
		map[k] = v;
	}
	source.putLoginHeader("#"+JSON.stringify(map));
}
// ===== 登录 =====
function toLogin(){
	try{
		var url = "https://lucifer-club.com/login.php";
		try{ cookie.setCookie(url,""); }catch(e){}
		java.longToast("请在打开的网页中登录，登录完成后点右上角✓");
		try{
			java.startBrowserAwait(url,"登录露西弗俱乐部");
			var co = "";
			for(var i=0;i<5;i++){
				try{ co = String(cookie.getCookie(url)); }catch(e){}
				if(co && co.indexOf("lnfo") >= 0) break;
				try{ java.sleep(300); }catch(e){}
			}
			if(co && co.indexOf("lnfo") >= 0){
				try{ setHeaders("cookie="+encodeURIComponent(co)); }catch(e){}
				try{ cookie.setCookie(url, co); }catch(e){}
				var ok = false;
				try{
					var chk = String(java.ajax("https://lucifer-club.com/my_favorite.php") || "");
					ok = chk.indexOf("luf_forget") < 0 && chk.indexOf("书架列表") >= 0;
				}catch(e){}
				if(ok){
					try{ source.refreshExplore(); }catch(e){}
					java.longToast("✅ 登录成功！请下拉刷新【发现】页（我的收藏/分类）");
				}else{
					java.longToast("⚠️ Cookie 已保存但未生效，请再点一次登录重试");
				}
			}else{
				java.longToast("⚠️ 未检测到登录状态，请重新登录");
			}
		}catch(e){
			java.longToast("登录未完成，请重新尝试");
		}
	}catch(e){
		java.longToast("登录失败："+e);
	}
}
function logoff(){
	try{
		try{ java.ajax("https://lucifer-club.com/login.php?action=logoff"); }catch(e){}
		try{ cookie.removeCookie("https://lucifer-club.com"); }catch(e){}
		java.toast("已退出登录");
	}catch(e){ java.toast("退出失败："+e); }
}

// ===== 交流QQ群（点击申请入群）=====
function joinQQGroup(){
	var u = "mqqapi://card/show_pslcard?src_type=internal&version=1&card_type=group&uin=1097919737";
	try{
		java.openUrl(u);
		java.toast("已尝试打开QQ，若未跳转请手动搜索群号 1097919737");
	}catch(e){
		java.longToast("请手动在QQ中搜索群号 1097919737");
	}
}

// ===== 检查登录状态 =====
function checkLogin(){
	try{
		var co = String(cookie.getCookie("https://lucifer-club.com"));
		if(co.indexOf("lnfo") < 0){
			java.longToast("❌ 未登录：请先点「👤 登录/重新登录」");
			return;
		}
		var m = co.match(/lnfo=([^;]+)/);
		var name = "";
		if(m){
			try{
				var s = java.base64Decode(decodeURIComponent(m[1]));
				var um = String(s).match(/s:\d+:"([^"]+)"/);
				name = um ? um[1] : "";
			}catch(e){}
		}
		if(name){
			java.longToast("✅ 已登录，当前账号：「" + name + "」");
		}else{
			java.longToast("✅ 已登录（Cookie有效）");
		}
	}catch(e){
		java.toast("检查登录状态失败：" + e);
	}
}

